// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const modelRef = await ctx.chatluna.createChatModel("openai/gpt-5-nano")
//      ^?


const message = await modelRef.value?.invoke("你好，世界！")
console.log(message)
    //          ^?

[!TIP] 提示
自 ChatLuna 1.3.0 开始，ChatLuna 开始深度整合 vue 的响应式系统。如果返回的值为 ComputedRef ，则代表此值是可以根据其他配置改动进行变化的。请先创建这个值并保存到类或者其他地方里面，在需要的时候调用 ref.value 来获取真正的值。

[!WARNING] 警告
响应式获取的 value 可能会 undefined。
如果返回空值，则说明当前获取的模型或者其他值不存在。你需要提取判断并告知用户，需要的模型或者其他参数不存在。

ChatLunaChatModel 继承自 BaseChatModel。

你可以直接使用 BaseChatModel 的所有方法，并和 LangChain 的其他 API 无缝衔接。

71.text:
ChatLunaChatModel 也可以传入消息列表：

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat"
import { HumanMessage, SystemMessage } from "@langchain/core/messages"

const modelRef = await ctx.chatluna.createChatModel("openai/gpt-5-nano")

const messages = [
    new SystemMessage("You are a helpful assistant."),
    new HumanMessage("你好，世界！")
]

const message = await modelRef.value?.invoke(messages)
console.log(message)
    //          ^?

并且支持多模态消息。实际可用内容取决于模型声明的 ModelCapabilities，常见能力包括图片、音频、视频和文件输入。下面是图片输入示例：

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat"
import { HumanMessage, SystemMessage } from "@langchain/core/messages"

const modelRef = await ctx.chatluna.createChatModel("openai/gpt-5-nano")

const messages = [
    new SystemMessage("You are a helpful assistant."),
    new HumanMessage({
        content: [
            {
                type: "image_url",
                image_url: {
                    // 也支持 base64 编码的图片
                    url: "https://example.com/image.png"
                }
            },
            {
                type: "text",
                content: "图片上的内容是什么？"
            }
        ]
    })
]

const message = await modelRef.value?.invoke(messages)
console.log(message)
    //          ^?

72.text:
在 ChatLuna 中，实际掌握各类模型和平台的是 PlatformService 类。

如果你需要获取全部可用的语言模型列表，可以调用 PlatformService 的 listAllModels 方法。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";
import { ModelType } from 'koishi-plugin-chatluna/llm-core/platform/types'

const modelsRef = ctx.chatluna.platform.listAllModels(ModelType.llm)
const models = modelsRef.value
//    ^?

ModelType 是一个枚举类型，定义了模型类型:

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
// @noErrors
import { Context, Schema } from 'koishi'
const ctx = new Context()
import type {} from "koishi-plugin-chatluna/services/chat";
import { ModelType } from 'koishi-plugin-chatluna/llm-core/platform/types'
type Prettify<T> = never | { [K in keyof T]: T[K] };

// ---cut---
type PureModelType = Prettify<typeof ModelType>
//        ^?

目前支持的模型类型有：

llm：大语言模型embeddings：嵌入模型reranker：重排序模型all：所有模型

73.text:
listAllModels 方法返回的是一系列模型信息数组。

我们可以获取指定模型的信息。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
// @noErrors
import { Context, Schema } from 'koishi'
const ctx = new Context()
import type {} from "koishi-plugin-chatluna/services/chat";
import { ModelType } from 'koishi-plugin-chatluna/llm-core/platform/types'
type Prettify<T> = never | { [K in keyof T]: T[K] };

// ---cut---
const modelInfo = ctx.chatluna.platform.findModel("openai/gpt-5-nano")

type ModelInfo = Prettify<typeof modelInfo.value>
//   ^?

返回的是一个 ModelInfo 对象，包含了模型的详细信息。具体的定义如下：

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
// @noErrors
import { Context, Schema } from 'koishi'
const ctx = new Context()
import type {} from "koishi-plugin-chatluna/services/chat";
import { ModelType, ModelCapabilities } from 'koishi-plugin-chatluna/llm-core/platform/types'
type Prettify<T> = never | { [K in keyof T]: T[K] };

// ---cut---
interface ModelInfo {
    // 模型名称
    name: string
    // 模型类型
    type: ModelType
    // 模型的上下文大小
    maxTokens: number
    // 模型支持的能力 (多模态，工具调用等)
    capabilities: ModelCapabilities[]
}

type PureCapabilities = Prettify<typeof ModelCapabilities>

常见能力枚举包括：

TextInput: 文本输入。ToolCall: 工具调用。ImageInput: 图片输入。Thinking: 思考内容输出。ImageGeneration: 图片生成。AudioInput: 音频输入。VideoInput: 视频输入。FileInput: 文件输入。

74.text:
ChatLuna 支持动态注册和使用 Tool。

基础用法
从 PlatformService 中获取 ChatLunaTool 实例:

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const chatlunaTool = ctx.chatluna.platform.getTool('web-search')
//      ^?

返回的是一个 ChatLunaTool 实例，其定义如下:

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
// @noErrors
import { Context, Schema } from 'koishi'
const ctx = new Context()
import type {} from "koishi-plugin-chatluna/services/chat";
import { ChatLunaBaseEmbeddings } from 'koishi-plugin-chatluna/llm-core/platform/model'
import { StructuredTool } from '@langchain/core/tools'
import { BaseMessage } from '@langchain/core/messages'
import { Session } from 'koishi'

// ---cut---
interface CreateToolParams {
    embeddings: ChatLunaBaseEmbeddings
}

interface ChatLunaTool {
    createTool: (params: CreateToolParams) => StructuredTool
    selector: (history: BaseMessage[]) => boolean
    authorization?: (session: Session) => boolean
    name?: string
    id?: string
}

其中:

createTool 方法用于创建一个 StructuredTool 实例selector 方法用于判断当前的对话历史是否需要使用该工具authorization 方法用于判断当前的会话是否有权限使用该工具name 为工具的名称id 为工具的唯一标识

创建工具时，需要传递 embeddings 参数。该参数用于工具在需要文本向量化时使用。

创建 web-search 工具的示例:

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const embeddingsRef = await ctx.chatluna.createEmbeddings("openai/text-embedding-3-small")
const chatlunaTool = ctx.chatluna.platform.getTool('web-search')

const tool = chatlunaTool.createTool({ embeddings: embeddingsRef.value })

const result = await tool.invoke("OpenAI 最近新闻")

75.text:
从 PlatformService 中获取可用的工具列表:

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const toolsRef = ctx.chatluna.platform.getTools()
const tools = toolsRef.value
//    ^?

常用工具的用法
ChatLunaTool 的 createTool 方法返回的是一个 StructuredTool 实例。

不同的工具在调用时需要不同的参数。这里介绍几个常用工具的用法。

常用工具的用法 > web-search
web-search 工具用于在互联网上搜索信息。

直接调用即可，传入的参数即为搜索的关键词。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const embeddingsRef = await ctx.chatluna.createEmbeddings("openai/text-embedding-3-small")
const chatlunaTool = ctx.chatluna.platform.getTool('web-search')

const tool = chatlunaTool.createTool({ embeddings: embeddingsRef.value })

const result = await tool.invoke("OpenAI 最近新闻")

76.text:
web-browser 工具基于 puppeteer 实现，用于在浏览器中打开网页并进行交互。

使用时需要按照特定格式传入参数 action、params 和 url。

支持的操作包括:

open [url]: 打开一个网页 (必须作为第一个操作)summarize [search_text?]: 简单总结当前页面内容，可选择性地指定搜索文本text [search_text?]: 获取当前页面的文本内容，可选择性地指定搜索文本select [selector]: 使用选择器获取特定 div 的内容previous: 返回上一页get-html: 获取当前页面的 HTML 内容get-structured-urls: 获取当前页面的结构化 URL 列表

使用示例:

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const embeddingsRef = await ctx.chatluna.createEmbeddings("openai/text-embedding-3-small")
const chatlunaTool = ctx.chatluna.platform.getTool('web-browser')

const tool = chatlunaTool.createTool({ embeddings: embeddingsRef.value })

const openResult = await tool.invoke({
    action: "open",
    url: "https://example.com"
})

const summaryResult = await tool.invoke({
    action: "summarize",
    url: "https://example.com"
})

const selectResult = await tool.invoke({
    action: "select",
    params: "main-content",
    url: "https://example.com"
})

77.text:
ChatLuna 提供了强大的预设系统，可以为模型定义不同的角色和行为模式。

基本用法
使用 chatluna 服务中的 preset 属性来获取预设。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const presetRef = ctx.chatluna.preset.getPreset("chatgpt")
const preset = presetRef.value
//      ^?


console.log(preset)

返回的预设是一个 PresetTemplate 对象，包含了预设的所有信息。

获取可用的预设
在 ChatLuna 中，预设由 PresetService 类管理。

如果你需要获取全部可用的预设列表，可以调用 PresetService 的 getAllPreset 方法。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const presetsRef = ctx.chatluna.preset.getAllPreset()
const presets = presetsRef.value
//    ^?


console.log(presets)

getAllPreset 方法接受一个可选参数:

concatKeyword: 是否将触发关键词拼接为字符串，默认为 true

当 concatKeyword 为 true 时，返回的是触发关键词拼接的字符串数组（如 ["chatgpt, gpt"]）。

当 concatKeyword 为 false 时，返回的是第一个触发关键词的数组（如 ["chatgpt"]）。

78.text:
ChatLuna 允许获取默认预设（通常是 sydney），如果没有找到则返回第一个加载的预设。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const defaultPresetRef = ctx.chatluna.preset.getDefaultPreset()
const defaultPreset = defaultPresetRef.value
//      ^?


console.log(defaultPreset)

基于预设创建聊天链
预设是聊天链的核心组成部分。你可以使用预设来创建聊天提示词，然后创建聊天链。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";
import { ChatLunaChatPrompt } from 'koishi-plugin-chatluna/llm-core/chain/prompt'
import { computed } from 'koishi-plugin-chatluna'

const modelRef = await ctx.chatluna.createChatModel("openai/gpt-5-nano")
const presetRef = ctx.chatluna.preset.getPreset('chatgpt')

const prompt = computed(() => {
    const model = modelRef.value
    return new ChatLunaChatPrompt({
        preset: presetRef,
        tokenCounter: (text) => model.getNumTokens(text),
        sendTokenLimit: model.getModelMaxContextSize(),
        promptRenderService: ctx.chatluna.promptRenderer,
        contextManager: ctx.chatluna.contextManager
    })
})

const chain = computed(() => prompt.value.pipe(modelRef.value))

ChatLunaChatPrompt 接受以下参数:

preset: 预设的计算引用tokenCounter: Token 计数函数，用于计算文本的 Token 数量sendTokenLimit: 发送消息的 Token 限制promptRenderService: 提示词渲染服务contextManager: 上下文管理服务，用于组装历史消息与上下文注入

79.text:
使用预设和模型创建一个完整的对话链示例。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";
import { ChatLunaChatPrompt } from 'koishi-plugin-chatluna/llm-core/chain/prompt'
import { computed } from 'koishi-plugin-chatluna'
import { HumanMessage } from '@langchain/core/messages'

const modelRef = await ctx.chatluna.createChatModel("openai/gpt-5-nano")
const presetRef = ctx.chatluna.preset.getPreset('sydney')

const prompt = computed(() => {
    const model = modelRef.value
    return new ChatLunaChatPrompt({
        preset: presetRef,
        tokenCounter: (text) => model.getNumTokens(text),
        sendTokenLimit: model.getModelMaxContextSize(),
        promptRenderService: ctx.chatluna.promptRenderer,
        contextManager: ctx.chatluna.contextManager
    })
})

const chain = computed(() => prompt.value.pipe(modelRef.value))

const response = await chain.value.invoke({
    input: new HumanMessage("你好，请介绍一下自己"),
    // 历史对话记录
    chat_history: [],
    // 预设变量
    variables: {}
})

console.log(response.content)

调用 invoke 方法时传入的参数包含:

input: 用户输入的消息（HumanMessage 实例）chat_history: 历史对话记录数组variables: 用于渲染预设模板的变量对象

80.text:
预设也可以与 Agent 框架结合使用，为 Agent 提供角色定位和行为指导。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";
import { createAgentExecutor, createToolsRef } from 'koishi-plugin-chatluna/llm-core/agent'
import { ChatLunaChatPrompt } from 'koishi-plugin-chatluna/llm-core/chain/prompt'
import type { ChatLunaTool } from 'koishi-plugin-chatluna/llm-core/platform/types'
import { computed } from 'koishi-plugin-chatluna'

const modelRef = await ctx.chatluna.createChatModel("openai/gpt-5-nano")
const embeddingsRef = await ctx.chatluna.createEmbeddings("openai/text-embedding-3-small")
const presetRef = ctx.chatluna.preset.getPreset('sydney')

const enabledTools = ['web-search', 'web-browser']
const toolsRef = computed(() =>
    enabledTools.map(
        (toolName) => ctx.chatluna.platform.getTool(toolName) satisfies ChatLunaTool
    )
)

const toolsRefCreated = createToolsRef({
    tools: toolsRef,
    embeddings: embeddingsRef.value
})

const prompt = computed(() => {
    const model = modelRef.value
    return new ChatLunaChatPrompt({
        preset: presetRef,
        tokenCounter: (text) => model.getNumTokens(text),
        sendTokenLimit: model.getModelMaxContextSize(),
        promptRenderService: ctx.chatluna.promptRenderer,
        contextManager: ctx.chatluna.contextManager
    })
})

const executorRef = createAgentExecutor({
    llm: modelRef,
    tools: toolsRefCreated.tools,
    prompt: prompt.value,
    agentMode: 'tool-calling',
    returnIntermediateSteps: true,
    handleParsingErrors: true
})

82.text:
Reranker 用于对一组候选文档按查询相关性重新排序。

一般常用于 RAG：先用向量数据库召回较多候选，再用 reranker 选出最相关的片段。

基本用法
使用 ctx.chatluna.createReranker() 创建 reranker 响应式引用。

代码 (ts)
import type {} from "koishi-plugin-chatluna/services/chat";

const rerankerRef = await ctx.chatluna.createReranker("cohere/rerank-v3.5");
const reranker = rerankerRef.value;

if (!reranker) {
  throw new Error("reranker not available");
}

const results = await reranker.rerank(
  [
    "ChatLuna 是 Koishi 下的大语言模型聊天插件。",
    "Koishi 是一个跨平台聊天机器人框架。",
  ],
  "ChatLuna 是什么？",
  { topN: 2 },
);

console.log(results);
// [{ index: 0, relevanceScore: 0.98 }, ...]

也可以分开传平台名和模型名：

代码 (ts)
const rerankerRef = await ctx.chatluna.createReranker("cohere", "rerank-v3.5");

获取可用模型
代码 (ts)
import { ModelType } from "koishi-plugin-chatluna/llm-core/platform/types";

const modelsRef = ctx.chatluna.platform.listAllModels(ModelType.reranker);
const models = modelsRef.value;

作为 LangChain Compressor 使用
ChatLunaReranker 继承自 LangChain 的 BaseDocumentCompressor，可以直接接入需要 compressor 的检索链。

代码 (ts)
const rerankedDocs = await reranker.compressDocuments(documents, "用户问题");

compressDocuments() 会保留原始 document，并在 metadata.relevanceScore 写入相关性分数。

84.text:
ChatLuna 提供了向量数据库的集成能力，用于高效存储和检索向量化的文本数据。

向量数据库是 LLM 应用的核心基础设施之一，它通过存储文本的向量表示，实现了基于语义的相似度搜索，为 LLM 提供外部知识库和记忆能力。

[!TIP] 提示
创建向量数据库时还需要指定嵌入模型，请参考 嵌入模型。

基于内存的向量数据库
如果只需要临时性的向量检索，可以创建内存中的向量数据库。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";
import { MemoryVectorStore } from 'koishi-plugin-chatluna/llm-core/vectorstores'

const embeddingsRef = await ctx.chatluna.createEmbeddings("openai/text-embedding-3-small")

const store = await MemoryVectorStore.fromExistingIndex(embeddingsRef.value)
//    ^?

85.text:
如果需要持久化的向量存储，则需要从 PlatformService 中创建支持持久化的向量数据库。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const embeddingsRef = await ctx.chatluna.createEmbeddings("openai/text-embedding-3-small")

const store = await ctx.chatluna.platform.createVectorStore(
    'faiss',
    {
        embeddings: embeddingsRef.value,
        key: "my-vector-store-key"
    }
)

PlatformService 的 createVectorStore 方法传递两个参数，第一个参数是向量数据库的类型，第二个参数是向量数据库的配置。

其中配置对象的属性如下：

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
// @noErrors
import { Context, Schema } from 'koishi'
const ctx = new Context()
import type {} from "koishi-plugin-chatluna/services/chat";
import { ChatLunaBaseEmbeddings } from 'koishi-plugin-chatluna/llm-core/platform/model'

// ---cut---
interface CreateVectorStoreParams {
    // 向量数据库的唯一标识
    key?: string
    // 嵌入模型
    embeddings: ChatLunaBaseEmbeddings
}

在使用持久化存储时，强烈建议设置 key 属性作为向量数据库的唯一标识符，这样可以在后续操作中准确检索到对应的向量数据库实例。

[!TIP] 提示
需要注意，每种向量数据库类型都有其特定的数据存储位置和方式。
为了确保数据获取的一致性，建议在项目中统一使用同一种向量数据库类型。

86.text:
当前应直接读取 ctx.chatluna.platform.vectorStores。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const vectorStoresRef = ctx.chatluna.platform.vectorStores
const vectorStores = vectorStoresRef.value
//    ^?

从用户配置中创建
ChatLuna 的主插件中允许用户设置 defaultVectorStore 配置项，用于指定默认的向量数据库。

开发者也可以直接使用这个配置项指定的向量数据库类型来创建向量数据库。

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context, Schema } from 'koishi'
import { computed } from "koishi-plugin-chatluna";

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat";

const embeddingsRef = await ctx.chatluna.createEmbeddings(ctx.chatluna.config.defaultEmbeddings)

const vectorStorePromise = computed(() => ctx.chatluna.platform.createVectorStore(
    ctx.chatluna.config.defaultVectorStore,
    {
        embeddings: embeddingsRef.value,
        key: "my-vector-store-key"
    }
))

// 在使用向量数据库，请总是 await
const vectorStore = await vectorStorePromise.value
//     ^?

87.text:
ChatLuna 也提供 API，来接入其他的嵌入模型。

使用脚手架创建适配器
我们强烈建议使用 ChatLuna 提供的脚手架来创建模型适配器插件。如果你还没有创建适配器项目，请先参考 大语言模型 文档创建适配器项目。

实现 Embeddings 支持
如果你的平台同时支持大语言模型和嵌入模型，推荐在同一个适配器中实现两者。

实现 Embeddings 支持 > 1. 修改客户端基类
将 src/client.ts 中的基类从 PlatformModelClient 改为 PlatformModelAndEmbeddingsClient：

实现 Embeddings 支持 > 1. 修改客户端基类
代码 (ts)
export class YourPlatformClient extends PlatformModelAndEmbeddingsClient<ClientConfig> {
    platform = 'yourplatform'

    private _requester: YourPlatformRequester

    constructor(
        ctx: Context,
        private _config: Config,
        public plugin: ChatLunaPlugin
    ) {
        super(ctx, plugin.platformConfigPool)

        this._requester = new YourPlatformRequester(
            ctx,
            plugin.platformConfigPool,
            _config,
            plugin
        )
    }

    async refreshModels(): Promise<ModelInfo[]> {
        const rawModels = [
            // 语言模型
            ['gpt-4', 8192, ModelType.llm],
            ['gpt-3.5-turbo', 4096, ModelType.llm],
            // 嵌入模型
            ['text-embedding-3', 8192, ModelType.embeddings],
            ['text-embedding-small', 8192, ModelType.embeddings],
        ] as [string, number, ModelType][]

        return rawModels.map(([model, maxTokens, type]) => {
            return {
                name: model,
                type,
                capabilities: [],
                maxTokens
            } as ModelInfo
        })
    }

    protected _createModel(
        model: string
    ): ChatLunaChatModel | ChatLunaBaseEmbeddings {
        const info = this._modelInfos[model]

        if (info == null) {
            throw new ChatLunaError(ChatLunaErrorCode.MODEL_NOT_FOUND)
        }

        // 根据模型类型创建不同的实例
        if (info.type === ModelType.llm) {
            return new ChatLunaChatModel({
                modelInfo: info,
                requester: this._requester,
                model,
                modelMaxContextSize: info.maxTokens,
                maxTokenLimit: Math.floor(
                    (info.maxTokens || 100_000) * this._config.maxContextRatio
                ),
                frequencyPenalty: this._config.frequencyPenalty,
                presencePenalty: this._config.presencePenalty,
                timeout: this._config.timeout,
                temperature: this._config.temperature,
                maxRetries: this._config.maxRetries,
                llmType: 'yourplatform'
            })
        }

        // 创建 Embeddings 模型实例
        return new ChatLunaEmbeddings({
            client: this._requester,
            model,
            maxRetries: this._config.maxRetries
        })
    }
}

