实现 Embeddings 支持 > 3. 实现要点 > 返回值
根据输入类型返回不同格式：

如果输入是单个字符串，返回 number[]（一维向量）如果输入是字符串数组，返回 number[][]（向量矩阵）

实现 Embeddings 支持 > 3. 实现要点 > 示例响应处理
以 Gemini 为例：

代码 (ts)
function embeddings(
    params: EmbeddingsRequestParams
): Promise<number[] | number[][]> {
    if (typeof params.input === 'string') {
        params.input = [params.input]
    }

    try {
        const response = await this._post(
            `models/${params.model}:batchEmbedContents`,
            {
                requests: params.input.map((input) => {
                    return {
                        model: `models/${params.model}`,
                        content: {
                            parts: [{ text: input }]
                        }
                    }
                })
            }
        )

        const data = await response.text()
        const result = JSON.parse(data)

        if (result.embeddings && result.embeddings.length > 0) {
            return result.embeddings.map((embedding) => {
                return embedding.values
            })
        }

        throw new Error(
            'error when calling gemini embeddings, Result: ' +
            JSON.stringify(result)
        )
    } catch (e) {
        const error = new Error(
            'error when calling gemini embeddings, Result: ' + e.message
        )
        error.stack = e.stack
        error.cause = e.cause
        logger.debug(e)

        throw new ChatLunaError(ChatLunaErrorCode.API_REQUEST_FAILED, error)
    }
}

