// @strictNullChecks: false
import { ChatLunaPlugin } from 'koishi-plugin-chatluna/services/chat'
import { Context, Schema } from 'koishi'

// ---cut-start---
export interface Config extends ChatLunaPlugin.Config {}
// ---cut-end---

export function apply(ctx: Context, config: Config) {
    const plugin = new ChatLunaPlugin(ctx, config, 'your-plugin-name', false)

    ctx.on('ready', async () => {
        // 继续...
    })
}

[!NOTE]
如果你的插件不需要注册模型适配器，ChatLunaPlugin 的构造函数需要传入 false 作为第四个参数。
该参数默认为 true，表示插件需要注册模型适配器。

创建 Tool
参考 LangChain 文档 创建你的 Tool。

ChatLuna 目前仍使用较老的 API 创建 Tool，下面是一个示例（使用 BuiltUserToastTool）：

106.text:
代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Tool } from '@langchain/core/tools'
import { Context } from 'koishi'

const ctx = new Context()

// ---cut---
import type {} from "koishi-plugin-chatluna/services/chat"
import type { ChatLunaToolRunnable } from 'koishi-plugin-chatluna/llm-core/platform/types'

export class BuiltUserToastTool extends Tool {
    name = 'built_user_toast'

    description = `Use this tool to notify the user about task changes, progress updates, or new developments during task execution. This is specifically for informational updates and notifications.

When to use:
- Task status has changed or progressed
- New developments or findings during execution
- Intermediate results that don't require user response
- Progress notifications during long-running tasks
- Completion notifications

Do NOT use this tool when:
- You need user input or confirmation (use built_user_confirm instead)
- You need user to choose between options (use built_question instead)
- Sending final results that end the conversation`

    constructor(private ctx: Context) {
        super()
    }

    /** @ignore */
    async _call(input: string, _, config: ChatLunaToolRunnable) {
        const session = config.configurable.session

        try {
            const elements = (
                await this.ctx.chatluna.renderer.render({
                    content: input
                })
            ).flatMap((message) => {
                const elements = message.element
                if (elements instanceof Array) {
                    return elements
                } else {
                    return [elements]
                }
            })

            await session.send(elements)
            return 'Message sent successfully. '
        } catch (error) {
            return 'An error occurred while sending your message. Please try again.'
        }
    }
}

107.text:
调用 ChatLunaPlugin 实例的 registerTool 方法注册 Tool：

代码 (ts)
// @noImplicitAny: false
// @strictNullChecks: false
import { Context } from 'koishi'
import { ChatLunaPlugin } from 'koishi-plugin-chatluna/services/chat'
import { Tool } from '@langchain/core/tools'
import type { ChatLunaToolRunnable } from 'koishi-plugin-chatluna/llm-core/platform/types'

const ctx = new Context()

export class BuiltUserToastTool extends Tool {
    name = 'built_user_toast'
    description = 'A tool for sending toast messages'
    constructor(private ctx: Context) { super() }
    async _call(input: string, _, config: ChatLunaToolRunnable) { return 'ok' }
}

// ---cut-start---
export interface Config extends ChatLunaPlugin.Config {}
// ---cut-end---

// ---cut---
export function apply(ctx: Context, config: Config) {
    const plugin = new ChatLunaPlugin(ctx, config, 'your-plugin-name', false)

    ctx.on('ready', async () => {
        plugin.registerTool('built_user_toast', {
            selector(history) {
                // 总是激活此工具（根据历史聊天记录判断）
                return true
            },

            authorization(session) {
                // 授权检查，返回 true 则允许使用
                return true
            },

            createTool(params) {
                // 创建工具实例
                return new BuiltUserToastTool(ctx)
            }
        })
    })
}

registerTool 方法接收两个参数：

108.text:
name: 工具名称（字符串）tool: ChatLunaTool 配置对象selector: 工具激活的选择器函数参数：history - 历史聊天记录数组返回：boolean - true 激活工具，false 不激活用途：根据对话历史判断是否需要此工具authorization: 授权检查函数参数：session - 当前会话对象返回：boolean - true 允许使用，false 拒绝使用用途：判断当前用户是否有权限使用该工具createTool: 工具实例创建函数参数：params - 工具参数session - 当前会话对象返回：Tool 实例用途：创建并返回工具的实例meta: 工具元数据（推荐填写）source: 工具来源常见值：core、extension、mcp、actiongroup: 工具所属分组如：search、plugin-commontags: 工具标签列表用于分类、筛选和展示defaultAvailability: 工具的默认可用性配置enabled: 是否默认启用main: 是否在主聊天模式中默认可用chatluna: 是否在 ChatLuna 主能力中默认可用characterScope: 是否在伪装插件中默认可用all: 群聊和私聊都默认可用group: 仅群聊默认可用private: 仅私聊默认可用none: 默认不在伪装插件中启用

注册 Tool > 工具元数据
当前 ChatLuna 的工具注册，通常都会补充 meta 字段。虽然它不是强制项，但推荐在开发插件时始终填写，便于工具系统、配置界面和其他上层功能正确识别工具来源、分组与默认启用范围。

示例：

代码 (ts)
plugin.registerTool('web_search', {
    description: SEARCH_TOOL_DESCRIPTION,
    selector() {
        return true
    },
    createTool(params) {
        return new SearchTool(...)
    },
    meta: {
        source: 'extension',
        group: 'search',
        tags: ['search', 'web'],
        defaultAvailability: {
            enabled: true,
            main: true,
            chatluna: true,
            characterScope: 'all'
        }
    }
})

如果你的工具是为伪装插件的回复流程服务的，建议你明确设置 characterScope，避免工具默认暴露到不合适的会话范围。

111.text:
调用 ctx.chatluna_character.registerReplyToolField() 注册字段。该方法返回一个注销函数，调用后可移除已注册的字段。

代码 (ts)
import { Context } from 'koishi'
import type {} from 'koishi-plugin-chatluna-character'

export function apply(ctx: Context) {
    // 注册一个自定义字段
    const dispose = ctx.chatluna_character.registerReplyToolField({
        name: 'poke',

        schema: {
            type: 'string',
            description: 'Platform user ID to poke.'
        },

        // 仅在非私聊的 OneBot 平台上可用
        isAvailable(ctx, session) {
            return !session.isDirect && session.platform === 'onebot'
        },

        // 模型调用 character_reply 并传入 poke 字段时执行
        async invoke(ctx, session, value) {
            if (typeof value !== 'string') return
            // 执行戳一戳操作……
        },

        // 将工具调用结果渲染为 XML，写入对话历史
        render(ctx, session, value) {
            if (typeof value !== 'string') return undefined
            return `<poke user_id="${value}" />`
        }
    })

    // 插件卸载时自动注销
    ctx.on('dispose', dispose)
}

为伪装插件的回复工具挂载自定义字段 > 工作流程
注册的字段会参与以下流程：

构建工具参数：伪装插件在创建 character_reply 工具时，遍历所有已注册字段，对通过 isAvailable 检查的字段，将其 schema 添加到工具的参数定义中。执行回调：当模型调用 character_reply 并传入了某个自定义字段的值时，伪装插件会调用该字段的 invoke 回调。渲染到历史：在将工具调用结果写入对话历史时，伪装插件会调用每个字段的 render 回调，将返回的 XML 字符串插入到 块中，使模型在后续轮次中可以看到之前的操作记录。

112.text:
本页说明如何为 ChatLuna 接入新的 reranker 平台。

客户端类型
按平台能力选择客户端基类：

PlatformRerankerClient: 只提供 reranker。PlatformModelEmbeddingsAndRerankerClient: 同时提供大语言模型、嵌入模型和 reranker。

代码 (ts)
import { PlatformRerankerClient } from 'koishi-plugin-chatluna/llm-core/platform/client'
import { ChatLunaReranker } from 'koishi-plugin-chatluna/llm-core/platform/rerank'
import { ModelType, type ModelInfo } from 'koishi-plugin-chatluna/llm-core/platform/types'
import { ChatLunaError, ChatLunaErrorCode } from 'koishi-plugin-chatluna/utils/error'

export class YourRerankerClient extends PlatformRerankerClient<ClientConfig> {
  platform = 'yourplatform'

  constructor(
    ctx: Context,
    private config: Config,
    private requester: YourRequester,
    plugin: ChatLunaPlugin,
  ) {
    super(ctx, plugin.platformConfigPool)
  }

  async refreshModels(): Promise<ModelInfo[]> {
    return [
      {
        name: 'rerank-large',
        type: ModelType.reranker,
        capabilities: [],
        maxTokens: 8192,
      },
    ]
  }

  protected _createModel(model: string): ChatLunaReranker {
    const info = this._modelInfos[model]
    if (!info) throw new ChatLunaError(ChatLunaErrorCode.MODEL_NOT_FOUND)

    return new ChatLunaReranker({
      client: this.requester,
      model,
      maxRetries: this.config.maxRetries,
      timeout: this.config.timeout,
    })
  }
}

113.text:
Requester 需要实现 rerank()。

代码 (ts)
import {
  ModelRequester,
  type RerankerRequester,
  type RerankerRequestParams,
  type RerankerResult,
} from 'koishi-plugin-chatluna/llm-core/platform/api'

export class YourRequester extends ModelRequester implements RerankerRequester {
  async rerank(params: RerankerRequestParams): Promise<RerankerResult[]> {
    const response = await this.post('rerank', {
      model: params.model,
      query: params.query,
      documents: params.documents,
      top_n: params.topN,
      max_chunks_per_doc: params.maxChunksPerDoc,
    }, {
      signal: params.signal,
    })

    const data = await response.json() as {
      results: { index: number; relevance_score: number }[]
    }

    return data.results.map((item) => ({
      index: item.index,
      relevanceScore: item.relevance_score,
    }))
  }
}

注册客户端
代码 (ts)
const plugin = new ChatLunaPlugin(ctx, config, 'yourplatform')

plugin.parseConfig((config) => config.apiKeys.map(([apiKey]) => ({
  apiKey,
  apiEndpoint: config.apiEndpoint,
})))

plugin.registerClient(() => {
  const requester = new YourRequester(ctx, plugin.platformConfigPool, config, plugin)
  return new YourRerankerClient(ctx, config, requester, plugin)
})

ctx.on('ready', () => plugin.initClient())

